    fputs("  larimar <file.lar> [args]     build one file and run it (with the bundled tcc when there is one:\n", stdout);
    fputs("                                it starts fast); its own arguments after '--' when they look like ours\n", stdout);
    fputs("  larimar c <file.lar>          print the generated C of a file\n", stdout);
    fputs("  larimar <file.lar> -o <out.c> write the generated C of a file\n", stdout);
